//! Checks the port against tests/parity.json, generated by running the Python version
//! (scripts/parity/gen_fixtures.py).

use std::sync::LazyLock;

use serde_json::{json, Value};

use crate::host::{parse_message, Record};
use crate::logic::*;
use crate::model::{Context, Kind, Page, Selection, Window};
use crate::store::Store;

static FIXTURES: LazyLock<Value> = LazyLock::new(|| {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../tests/parity.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("tests/parity.json")).expect("valid json")
});

fn cases(key: &str) -> &'static Vec<Value> {
    FIXTURES[key].as_array().unwrap_or_else(|| panic!("no fixtures for {key}"))
}

fn s(v: &Value) -> &str {
    v.as_str().unwrap_or_default()
}

fn opt<T: serde::de::DeserializeOwned>(v: &Value) -> Option<T> {
    (!v.is_null()).then(|| serde_json::from_value(v.clone()).expect("fixture shape"))
}

fn favicon_lookup(case: &Value) -> impl Fn(&str) -> bool {
    let names: Vec<String> = case["favicons"].as_array().into_iter().flatten().map(|h| favicon_name(s(h))).collect();
    move |name: &str| names.iter().any(|n| n == name)
}

#[test]
fn parse_sent_matches() {
    for c in cases("parse_sent") {
        assert_eq!(parse_sent(s(&c["raw"]), s(&c["order"])), s(&c["expected"]), "{c}");
    }
}

#[test]
fn window_source_matches() {
    for c in cases("window_source") {
        let w = Window { class: s(&c["window"]["class"]).into(), title: s(&c["window"]["title"]).into() };
        assert_eq!(window_source(&w), s(&c["expected"]), "{c}");
    }
}

#[test]
fn browser_context_matches() {
    for c in cases("browser_context") {
        let selection: Option<Selection> = opt(&c["selection"]);
        let page: Option<Page> = opt(&c["page"]);
        let got = browser_context(
            s(&c["text"]),
            s(&c["window_title"]),
            selection.as_ref(),
            page.as_ref(),
            c["now"].as_f64().unwrap(),
            &favicon_lookup(c),
        );
        assert_eq!(serde_json::to_value(&got).unwrap(), c["expected"], "{}", c["name"]);
    }
}

#[test]
fn page_text_matches() {
    for c in cases("page_text") {
        let selection: Option<Selection> = opt(&c["selection"]);
        assert_eq!(page_text(s(&c["text"]), selection.as_ref(), c["now"].as_f64().unwrap()), s(&c["expected"]), "{}", c["name"]);
    }
}

#[test]
fn native_host_matches() {
    for c in cases("native_host") {
        let mut favicons = Vec::new();
        let mut page: Option<Page> = None;
        let mut selection: Option<Selection> = None;
        let mut replies = Vec::new();
        let messages = c["messages"].as_array().unwrap();
        for (i, m) in messages.iter().enumerate() {
            let now = 1000.0 + i as f64;
            let mut save = |host: &str, _png: &[u8]| {
                let name = favicon_name(host);
                favicons.push(name.clone());
                Some(name)
            };
            let record = parse_message(s(m).as_bytes(), page.as_ref(), now, &mut save);
            replies.push(json!({ "ok": record.is_some() }));
            match record {
                Some(Record::Page(p)) => {
                    page = Some(p);
                }
                Some(Record::Selection(sel)) => {
                    selection = Some(sel);
                }
                None => {}
            }
        }
        let last = 1000.0 + (messages.len() - 1) as f64;
        let stamp = |v: f64| json!(if v >= last { "now" } else { "kept" });
        let mut got_sel = selection.map(|x| serde_json::to_value(x).unwrap()).unwrap_or(json!({}));
        if let Some(r) = got_sel.get_mut("received") {
            *r = stamp(r.as_f64().unwrap());
        }
        let mut got_page = page.map(|x| serde_json::to_value(x).unwrap()).unwrap_or(json!({}));
        for key in ["received", "since"] {
            if let Some(v) = got_page.get_mut(key) {
                *v = stamp(v.as_f64().unwrap());
            }
        }
        favicons.sort();
        favicons.dedup();
        assert_eq!(Value::Array(replies), c["replies"], "{} replies", c["name"]);
        assert_eq!(got_sel, c["selection"], "{} selection", c["name"]);
        assert_eq!(got_page, c["page"], "{} page", c["name"]);
        assert_eq!(json!(favicons), c["favicons"], "{} favicons", c["name"]);
    }
}

fn normalized(list: &[crate::model::Item]) -> Value {
    let mut v = serde_json::to_value(list).unwrap();
    for item in v.as_array_mut().unwrap() {
        let obj = item.as_object_mut().unwrap();
        obj.remove("id");
        for key in ["created", "archived"] {
            if obj.contains_key(key) {
                obj.insert(key.into(), json!("<ts>"));
            }
        }
    }
    v
}

#[test]
fn store_matches() {
    let mut store = Store::in_memory();
    for step in cases("store") {
        let op = step["op"].as_array().unwrap();
        let result = match s(&op[0]) {
            "add" => {
                let kind = if s(&op[1]) == "capture" { Kind::Capture } else { Kind::Prompt };
                let context: Context = opt(&op[4]).unwrap_or_default();
                store.add(kind, s(&op[2]), s(&op[3]), context)
            }
            "done" => {
                let id = store.items[op[1].as_u64().unwrap() as usize].id.clone();
                store.set_done(&id, true);
                true
            }
            "archive_done" => {
                store.clear_done();
                true
            }
            "restore" => {
                if let Some(id) = store.history.get(op[1].as_u64().unwrap() as usize).map(|i| i.id.clone()) {
                    store.restore(&id);
                }
                true
            }
            "forget_first" => {
                if let Some(id) = store.history.first().map(|i| i.id.clone()) {
                    store.forget(&id);
                }
                true
            }
            "delete" => {
                let id = store.items[op[1].as_u64().unwrap() as usize].id.clone();
                store.delete(&id);
                true
            }
            other => panic!("unknown op {other}"),
        };
        assert_eq!(json!(result), step["result"], "{op:?}");
        assert_eq!(normalized(&store.items), step["items"], "{op:?} items");
        assert_eq!(normalized(&store.history), step["history"], "{op:?} history");
    }
}

#[test]
fn capture_matches() {
    for c in cases("capture") {
        let expected = &c["expected"];
        let now = expected["now"].as_f64().unwrap();
        let ago = |v: &Value| v.as_f64().map(|a| now - a).unwrap_or(0.0);
        let title = s(&c["window_title"]);
        let window = Window {
            class: if title.ends_with(" - Brave") { "brave-browser" } else { "foot" }.into(),
            title: title.into(),
        };
        let page: Option<Page> = opt(&c["page"]);
        let selection: Option<Selection> = opt(&c["selection"]);
        let input = CaptureInput {
            selection_text: s(&c["primary"]),
            clock: SelectionClock { changed_at: ago(&c["changed_ago"]), captured_at: ago(&c["captured_ago"]) },
            now,
            window: &window,
            page: page.as_ref(),
            selection: selection.as_ref(),
        };
        let mut store = Store::in_memory();
        let applied = apply_capture(&mut store, decide_capture(&input, &|_| false), &window_source(&window));
        let item = store.items.last().map(|i| {
            let v = serde_json::to_value(i).unwrap();
            let keep = ["text", "source", "url", "host", "title"];
            Value::Object(v.as_object().unwrap().iter().filter(|(k, _)| keep.contains(&k.as_str())).map(|(k, v)| (k.clone(), v.clone())).collect())
        });
        assert_eq!(item.unwrap_or(Value::Null), expected["item"], "{} item", c["name"]);
        let notified: Vec<String> = applied.notice.into_iter().map(|n| n.0).collect();
        assert_eq!(json!(notified), expected["notified"], "{} notified", c["name"]);
        assert_eq!(json!(applied.consumed), expected["consumed"], "{} consumed", c["name"]);
    }
}
